INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-64-usa', 'N64', 'Star Fox 64 (USA)', '1997', 'Shooter', 'Nintendo', '4', 'Rail Shooter', 'On-rail shooter with branching paths and full voice acting.', 'Reach Venom and defeat Andross to save the galaxy.', 'The definitive North American sci-fi shooter from Nintendo.', 'Star Fox 64 (USA) is a cornerstone of the N64 library. Featuring a memorable cast, multiple paths to victory, and legendary boss fights, it offers endless replayability and intense dogfighting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-64-usa-rev-a', 'N64', 'Star Fox 64 (USA) (Rev A)', '1997', 'Shooter', 'Nintendo', '4', 'Rail Shooter', 'On-rail shooter with branching paths and refined performance.', 'Conquer the Lylat system in the most stable version of the game.', 'An updated revision of the North American Star Fox 64.', 'Star Fox 64 (USA) (Rev A) offers the most polished version of Fox''s adventure. Enjoy the same high-octane action and voice acting with minor bug fixes and improved performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-64-randomizer-beta40', 'N64', 'Star Fox 64 Randomizer Beta.40', '2023', 'Shooter', 'Independent', '1', 'Randomizer', 'On-rail shooter with randomized levels, items, and enemies.', 'Complete a unique, shuffled journey through the Lylat system.', 'A chaotic randomizer mod for the Star Fox 64 engine.', 'Star Fox 64 Randomizer Beta.40 transforms the classic campaign. Every playthrough is different as routes, boss encounters, and items are shuffled, providing a fresh challenge for veteran pilots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-64:-survival', 'N64', 'Star Fox 64: Survival', '2023', 'Shooter', 'Independent', '1', 'Survival Challenge', '3D action-shooter with wave-based survival mechanics.', 'Survive as long as possible against endless waves of enemies.', 'A specialized "survival" mod built on the Star Fox 64 engine.', 'Star Fox 64: Survival tests your combat endurance. Face increasing difficulty and swarms of enemy craft in this intense, high-score focused modification for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-soldier---vanishing-earth-japan', 'N64', 'Star Soldier - Vanishing Earth (Japan)', '1998', 'Shooter', 'Hudson Soft', '2', 'Vertical Shooter', 'Vertical scrolling shooter with cinematic 3D backgrounds.', 'Blast through enemy fleets to save Earth from a mechanical threat.', 'The Japanese version of the fast-paced Star Soldier revival.', 'Star Soldier - Vanishing Earth (Japan) offers classic "shmup" gameplay with modern 3D visuals. Master the scoring system and navigate through bullet-filled levels to defeat massive bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-soldier---vanishing-earth-usa', 'N64', 'Star Soldier - Vanishing Earth (USA)', '1998', 'Shooter', 'Hudson Soft', '2', 'Vertical Shooter', 'Vertical scrolling shooter with cinematic 3D backgrounds.', 'Neutralize the alien invasion and protect the solar system.', 'The North American release of the intense vertical shooter.', 'Star Soldier - Vanishing Earth (USA) is a treat for fans of arcade shooters. Featuring multiple weapon types and branching paths based on performance, it’s a high-energy action title for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-twins-japan', 'N64', 'Star Twins (Japan)', '1997', 'Platform', 'Nintendo', '2', 'Action Adventure', 'Third-person action-adventure with two playable characters.', 'Defeat the insectoid Mizar and save the galaxy from his swarm.', 'The Japanese version of the game known as Jet Force Gemini.', 'Star Twins (Japan) features deep exploration and intense combat. Control Juno and Vela as you rescue tribal creatures and upgrade your weapons to stop the galactic invasion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---rogue-squadron-europe-enfrde', 'N64', 'Star Wars - Rogue Squadron (Europe) (En,Fr,De)', '1998', 'Shooter', 'Factor 5', '1', 'Flight Combat', 'Mission-based flight combat featuring iconic Star Wars craft.', 'Complete various aerial objectives to defeat the Galactic Empire.', 'A high-fidelity Star Wars adventure for the European market.', 'Star Wars - Rogue Squadron (Europe) lets you pilot X-wings, A-wings, and more. Battle across various planets, complete strategic missions, and earn medals in this technical showcase for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---rogue-squadron-europe-enfrde-rev-a', 'N64', 'Star Wars - Rogue Squadron (Europe) (En,Fr,De) (Rev A)', '1998', 'Shooter', 'Factor 5', '1', 'Flight Combat', 'Mission-based flight combat with technical refinements.', 'Overcome the Empire with improved game stability and logic.', 'An updated European revision of the Rogue Squadron flight sim.', 'Star Wars - Rogue Squadron (Europe) (Rev A) provides the smoothest version of the rebel campaign for PAL players. Experience the same epic space combat with minor technical improvements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---rogue-squadron-usa', 'N64', 'Star Wars - Rogue Squadron (USA)', '1998', 'Shooter', 'Factor 5', '1', 'Flight Combat', 'Mission-based flight combat featuring iconic Star Wars craft.', 'Lead Rogue Squadron to victory against the Imperial threat.', 'The definitive North American Star Wars flight action game.', 'Star Wars - Rogue Squadron (USA) is a must-play for fans of the franchise. With high-resolution graphics and cinematic sound, it delivers an authentic Star Wars experience across 16 intense missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---rogue-squadron-usa-rev-a', 'N64', 'Star Wars - Rogue Squadron (USA) (Rev A)', '1998', 'Shooter', 'Factor 5', '1', 'Flight Combat', 'Mission-based flight combat with technical refinements.', 'Secure the galaxy for the Rebellion in the most polished version.', 'An updated North American revision of the Rogue Squadron game.', 'Star Wars - Rogue Squadron (USA) (Rev A) is the most stable version of this classic. Enjoy the high-speed dogfights and mission-based gameplay with refined performance for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---shadows-of-the-empire-europe', 'N64', 'Star Wars - Shadows of the Empire (Europe)', '1996', 'Action', 'LucasArts', '1', 'Action Adventure', 'Third-person shooter and vehicular combat set in the Star Wars universe.', 'Complete missions as Dash Rendar to assist the Rebel Alliance.', 'A landmark N64 title bridging the gap between Episodes V and VI.', 'Star Wars - Shadows of the Empire (Europe) lets players relive the Battle of Hoth and beyond. Master diverse gameplay styles, from piloting snowspeeders to jetpack combat, in this essential Star Wars adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---shadows-of-the-empire-usa', 'N64', 'Star Wars - Shadows of the Empire (USA)', '1996', 'Action', 'LucasArts', '1', 'Action Adventure', 'Third-person shooter and vehicular combat set in the Star Wars universe.', 'Defeat Prince Xizor and his criminal empire to save Han Solo.', 'The North American release of the cinematic Star Wars classic.', 'Star Wars - Shadows of the Empire (USA) follows the journey of Dash Rendar. Experience iconic battles and explore the underworld of the galaxy in this fan-favorite title optimized for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---shadows-of-the-empire-usa-rev-a', 'N64', 'Star Wars - Shadows of the Empire (USA) (Rev A)', '1996', 'Action', 'LucasArts', '1', 'Action Adventure', 'Third-person shooter and vehicular combat with minor bug fixes.', 'Navigate the galaxy and survive the shadows of the empire.', 'An updated revision of the North American Star Wars adventure.', 'Star Wars - Shadows of the Empire (USA) (Rev A) provides the same high-stakes action with improved game stability and performance, ensuring a smoother journey through the Lylat and beyond.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---shadows-of-the-empire-usa-rev-b', 'N64', 'Star Wars - Shadows of the Empire (USA) (Rev B)', '1996', 'Action', 'LucasArts', '1', 'Action Adventure', 'Third-person shooter and vehicular combat with final logic updates.', 'Secure the future of the Rebellion in the most polished version.', 'The final technical revision of the Shadows of the Empire game.', 'Star Wars - Shadows of the Empire (USA) (Rev B) is the most refined version available on N64. Experience Dash Rendar’s missions with the highest level of technical polish and fixed asset behavior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---shutsugeki!-rogue-chuutai-japan', 'N64', 'Star Wars - Shutsugeki! Rogue Chuutai (Japan)', '1996', 'Action', 'LucasArts', '1', 'Action Adventure', 'Mission-based flight combat featuring iconic Star Wars craft.', 'Lead the Rogue Squadron to defeat the Imperial forces.', 'The Japanese localized version of the hit game Rogue Squadron.', 'Star Wars - Shutsugeki! Rogue Chuutai (Japan) brings high-speed aerial dogfights to Japanese fans. Pilot X-wings and snowspeeders through intense, mission-driven objectives in a galaxy far, far away.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---teikoku-no-kage-japan', 'N64', 'Star Wars - Teikoku no Kage (Japan)', '1996', 'Action', 'LucasArts', '1', 'Action Adventure', 'Third-person shooter and vehicular combat with Japanese localization.', 'Stop the Black Sun syndicate and help the Rebels.', 'The localized Japanese version of Shadows of the Empire.', 'Star Wars - Teikoku no Kage (Japan) offers the full cinematic experience of Dash Rendar''s story, fully translated for the Japanese N64 market, featuring all the classic combat and flight stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-episode-i---battle-for-naboo-europe', 'N64', 'Star Wars Episode I - Battle for Naboo (Europe)', '2000', 'Shooter', 'Factor 5', '1', 'Flight Combat', 'Mission-based vehicular combat across land, sea, and air.', 'Defeat the Trade Federation and liberate the planet Naboo.', 'A late-era N64 title using an enhanced Rogue Squadron engine.', 'Star Wars Episode I - Battle for Naboo (Europe) features incredible graphics and diverse vehicle selection. Take control of N-1 Starfighters and land speeders to save the planet in this intense action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-episode-i---battle-for-naboo-usa', 'N64', 'Star Wars Episode I - Battle for Naboo (USA)', '2000', 'Shooter', 'Factor 5', '1', 'Flight Combat', 'Mission-based vehicular combat across land, sea, and air.', 'Drive back the droid armies and secure Naboo''s freedom.', 'The North American release of the Battle for Naboo flight game.', 'Star Wars Episode I - Battle for Naboo (USA) pushes the N64 hardware to its limits. Experience epic scale battles and strategic mission objectives in this spiritual successor to Rogue Squadron.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-episode-i---racer-europe-enfrde', 'N64', 'Star Wars Episode I - Racer (Europe) (En,Fr,De)', '1999', 'Racing', 'LucasArts', '2', 'Arcade Racing', 'High-speed futuristic racing with anti-gravity pods.', 'Win the podracing championship across various dangerous planets.', 'A lightning-fast racer based on the iconic Phantom Menace scene.', 'Star Wars Episode I - Racer (Europe) delivers intense speed and customization. Upgrade your podracer and master the narrow tracks of Tatooine and beyond in this definitive N64 racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-episode-i---racer-japan', 'N64', 'Star Wars Episode I - Racer (Japan)', '1999', 'Racing', 'LucasArts', '2', 'Arcade Racing', 'High-speed futuristic racing with anti-gravity pods.', 'Become the ultimate podracing champion of the galaxy.', 'The Japanese release of the high-octane Star Wars racer.', 'Star Wars Episode I - Racer (Japan) brings the thrill of the Boonta Eve Classic to N64. Experience incredible frame rates and technical racing mechanics in this beautifully realized sci-fi simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-episode-i---racer-usa', 'N64', 'Star Wars Episode I - Racer (USA)', '1999', 'Racing', 'LucasArts', '2', 'Arcade Racing', 'High-speed futuristic racing with anti-gravity pods.', 'Defeat Sebulba and other rivals to win the podracing circuit.', 'The North American version of the acclaimed podracing game.', 'Star Wars Episode I - Racer (USA) is one of the fastest games on the system. Manage your engines, perform repairs on the fly, and discover shortcuts across multiple alien worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starcraft-64-australia', 'N64', 'StarCraft 64 (Australia)', '2000', 'Strategy', 'Blizzard Entertainment', '4', 'Real-Time Strategy', 'Real-time strategy with three distinct alien races.', 'Manage resources and build armies to conquer the sector.', 'The rare Australian PAL port of the legendary PC strategy game.', 'StarCraft 64 (Australia) brings the epic conflict between Terran, Zerg, and Protoss to the console. Features a specialized interface and local split-screen co-op, making it a unique RTS experience on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starcraft-64-germany-proto', 'N64', 'StarCraft 64 (Germany) (Proto)', '2000', 'Strategy', 'Blizzard Entertainment', '4', 'Prototype', 'Real-time strategy with localized German text and voice.', 'Complete the campaigns of all three races in this early build.', 'A rare German language prototype of the RTS classic.', 'StarCraft 64 (Germany) (Proto) provides a look at the localized development of the game. Experience the deep tactical gameplay and resource management in this unique European preview.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starcraft-64-usa', 'N64', 'StarCraft 64 (USA)', '2000', 'Strategy', 'Blizzard Entertainment', '4', 'Real-Time Strategy', 'Real-time strategy featuring the "Brood War" expansion content.', 'Master the unique strategies of each race to win the war.', 'The definitive North American console version of the RTS giant.', 'StarCraft 64 (USA) includes both the original campaign and the Brood War expansion. With optimized controls and exclusive N64 missions, it is a massive and deep strategy experience for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starline-the-platypus-64', 'N64', 'Starline The Platypus 64', '2023', 'Platform', 'Independent', '1', 'Indie Platformer', '3D platforming featuring a custom platypus character model.', 'Explore custom levels and collect items using aquatic abilities.', 'A creative character mod featuring Starline the Platypus in SM64.', 'Starline The Platypus 64 brings a unique character to the Mario 64 engine. Navigate through vibrant custom-built levels and enjoy the specialized animations and charm of this fan-made project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starshot---space-circus-fever-europe-enfrde', 'N64', 'Starshot - Space Circus Fever (Europe) (En,Fr,De)', '1998', 'Action', 'Infogrames', '1', 'Action Adventure', '3D platforming with a quirky space-circus theme and gadgets.', 'Save the Space Circus from a series of galactic mishaps.', 'A colorful and creative platformer developed by Infogrames.', 'Starshot - Space Circus Fever (Europe) follows a young acrobat in a vibrant galaxy. Use a variety of gadgets and interact with strange aliens in this imaginative and lighthearted N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starshot---space-circus-fever-usa-enfres', 'N64', 'Starshot - Space Circus Fever (USA) (En,Fr,Es)', '1998', 'Action', 'Infogrames', '1', 'Action Adventure', '3D platforming with a quirky space-circus theme and gadgets.', 'Explore diverse planets to help the space circus succeed.', 'The North American release of the unique space-themed platformer.', 'Starshot - Space Circus Fever (USA) offers a distinctive art style and humor. Navigate floating islands and mechanical worlds in this quirky 3D adventure featuring varied gameplay mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strange-fruits---melon', 'N64', 'Strange Fruits - Melon', '2023', 'Puzzle', 'Independent', '1', 'Experimental', '3D platforming in a surreal, fruit-themed custom environment.', 'Collect hidden stars within a giant melon-themed world.', 'A creative and colorful custom level for the Super Mario 64 engine.', 'Strange Fruits - Melon is a visually striking mod that places Mario in a world of giant produce. Solve environmental puzzles and navigate fruit-inspired structures in this unique N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stunt-racer-64-usa', 'N64', 'Stunt Racer 64 (USA)', '2000', 'Racing', 'Boss Game Studios', '1', 'Arcade Racing', 'High-stakes arcade racing with a focus on stunts and betting.', 'Win races and perform stunts to earn money and unlock cars.', 'A late-release arcade racer known for its high-quality graphics.', 'Stunt Racer 64 (USA) is one of the most visually impressive games on the system. Combine speed with mid-air tricks and manage your career to become the king of the stunt racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-b-daman---battle-phoenix-64-japan', 'N64', 'Super B-Daman - Battle Phoenix 64 (Japan)', '1998', 'Action', 'Hudson Soft', '2', 'Arena Battler', 'Action-puzzle gameplay based on the B-Daman toy line.', 'Defeat opponents in B-Daman battles by shooting marbles.', 'A Japan-exclusive title featuring the popular Battle Phoenix line.', 'Super B-Daman - Battle Phoenix 64 (Japan) brings the physical toy experience to the screen. Compete in various skill-based trials and explosive battles in this charming and competitive N64 game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-beatrice-64', 'N64', 'Super Beatrice 64', '2022', 'Platform', 'Independent', '1', 'Indie Platformer', '3D platforming featuring a custom Beatrice character model.', 'Explore the Mushroom Kingdom with new movement and aesthetics.', 'A character-focused mod for Super Mario 64.', 'Super Beatrice 64 introduces a new protagonist to the classic engine. Enjoy the iconic platforming levels with custom animations and a fresh character design in this fan-made N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bowling-japan', 'N64', 'Super Bowling (Japan)', '1999', 'Sports', 'ATHENA', '4', 'Bowling Simulation', 'Realistic bowling simulation with multiple modes and characters.', 'Achieve a perfect game and win professional tournaments.', 'The Japanese version of the detailed bowling simulation.', 'Super Bowling (Japan) offers precise controls and realistic physics. Choose your character and master the lanes in various environments, from classic halls to futuristic venues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bowling-usa', 'N64', 'Super Bowling (USA)', '1999', 'Sports', 'ATHENA', '4', 'Bowling Simulation', 'Realistic bowling simulation with multiple modes and characters.', 'Become a bowling legend by mastering the tournament mode.', 'The North American release of the realistic bowling sim.', 'Super Bowling (USA) features a variety of lanes and customizable options. With its focus on physics and timing, it provides one of the most authentic bowling experiences on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bowser-64', 'N64', 'Super Bowser 64', '2022', 'Platform', 'Independent', '1', 'Character Hack', '3D platforming featuring Bowser as the main protagonist.', 'Conquer the Mushroom Kingdom using Bowser''s power and size.', 'A total conversion mod that lets you play as the King of Koopas.', 'Super Bowser 64 flips the script on the classic adventure. Use Bowser''s unique strength and fire-breathing abilities to navigate levels and collect stars in this impressive N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bowsette-64-by-kaze-emanuar', 'N64', 'Super Bowsette 64 By Kaze Emanuar', '2022', 'Platform', 'Independent', '1', 'Character Hack', '3D platforming featuring the fan-favorite Bowsette character.', 'Explore the world of Mario 64 with a unique character swap.', 'A character mod by Kaze Emanuar featuring the Bowsette design.', 'Super Bowsette 64 By Kaze Emanuar brings the internet phenomenon to the N64. Experience custom models, voice lines, and animations in this high-quality character-focused modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-captain-falcon-64', 'N64', 'Super Captain Falcon 64', '2022', 'Platform', 'Independent', '1', 'Character Hack', '3D platforming with an ultra-powered Captain Falcon.', 'Navigate levels at extreme speeds using Falcon''s moveset.', 'A high-speed character mod for the Super Mario 64 engine.', 'Super Captain Falcon 64 combines F-Zero speed with Mario platforming. Use the Falcon Punch and high-velocity dashes to clear levels in record time in this intense N64 hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chaos-64', 'N64', 'Super Chaos 64', '2023', 'Platform', 'Independent', '1', 'Chaos Hack', '3D platforming with randomized and glitched level logic.', 'Survive a chaotic and unpredictable version of the Mushroom Kingdom.', 'A challenging "Chaos" mod that shuffles game events and assets.', 'Super Chaos 64 is an unpredictable adventure where anything can happen. Face random status effects, warped textures, and shifted level logic in this chaotic take on the N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-64', 'N64', 'Super Donkey Kong 64', '2023', 'Platform', 'Independent', '1', 'Character Hack', '3D platforming featuring Donkey Kong in the Mario 64 engine.', 'Collect bananas and stars using Donkey Kong''s signature moves.', 'A character-swap mod that brings DK to the world of SM64.', 'Super Donkey Kong 64 offers a new way to explore the castle. Utilize DK’s ground-pound and strength-based movement to navigate custom levels in this high-quality character modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dreams-64', 'N64', 'Super Dreams 64', '2023', 'Platform', 'Independent', '1', 'Dreamlike Platformer', '3D platforming in a surreal, dream-like custom environment.', 'Explore a world of clouds and imagination to find the Power Stars.', 'A visually artistic and peaceful mod for Super Mario 64.', 'Super Dreams 64 features soft aesthetics and creative level design. Wander through a sky-themed world and solve gentle puzzles in this atmospheric and charming N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-event-horizon', 'N64', 'Super Event Horizon', '2023', 'Shooter', 'Independent', '1', 'Indie Shooter', '3D platforming with a cosmic, sci-fi horror theme.', 'Navigate a dark space station and survive the event horizon.', 'A spooky and atmospheric custom mod based on the sci-fi movie.', 'Super Event Horizon brings sci-fi horror to the N64. Explore a desolate space station with custom textures and lighting, solving eerie puzzles to escape the darkness in this unique project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ice-64', 'N64', 'Super Ice 64', '2022', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', '3D platforming with slippery ice physics and winter themes.', 'Navigate frozen landscapes to collect stars despite the low friction.', 'A winter-themed Mario 64 mod with a focus on ice physics.', 'Super Ice 64 challenges your precision with slippery terrain. Explore beautifully crafted frozen worlds and master the art of momentum on ice in this chilly N64 platforming adventure.');
