INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-melee-adventure-64---ness', 'N64', 'Super Melee Adventure 64 - NESS', '2019', 'Action', 'ROM Hack Community', '1', 'Action Platformer', '3D action-platforming featuring Ness''s psychic abilities.', 'Use PSI powers and a baseball bat to navigate the kingdom.', 'A unique crossover mod featuring the protagonist of EarthBound.', 'Super Melee Adventure 64 - NESSS brings Mother series charm to the N64. Use custom psychic-themed attacks and Ness''s signature model to explore and defeat Bowser.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-niko-64', 'N64', 'Super Niko 64', '2020', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', '3D platforming featuring Niko from OneShot.', 'Guide the light-bearer through the world of Mario 64.', 'A charming character swap featuring the protagonist of OneShot.', 'Super Niko 64 is a whimsical crossover mod. Explore the Mushroom Kingdom with Niko’s custom model and light-themed aesthetic, offering a peaceful and unique N64 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-oofio-64', 'N64', 'Super Oofio 64', '2020', 'Platformer', 'ROM Hack Community', '1', 'Meme Hack', '3D platforming with "Oof" sound effects and meme-themed assets.', 'Collect stars while navigating a world full of internet humor.', 'A funny and surreal mod based on the "Oof" sound phenomenon.', 'Super Oofio 64 is a lighthearted take on the original game. Every interaction is packed with memes and custom sound effects, making for a hilarious and quirky N64 playthrough.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pizza-time-64', 'N64', 'Super Pizza Time 64', '2021', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', '3D platforming with a fast-paced "Pizza Tower" style mechanic.', 'Dash through levels at high speeds to collect stars.', 'A high-energy mod inspired by the gameplay of Pizza Tower.', 'Super Pizza Time 64 brings momentum-heavy platforming to the N64. Master the dash and the frantic pace of modern indie hits within the classic Mario 64 engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-releasio-64', 'N64', 'Super Releasio 64', '2021', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', 'Surreal 3D platforming with distorted textures and sounds.', 'Try to navigate a world that is visually and aurally "cursed."', 'A famous "weird" mod featuring Toad''s face on every texture.', 'Super Releasio 64 is an internet legend. Experience a surreal nightmare where every surface is a distorted Toad, offering a bizarre and uniquely challenging N64 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-releasio-64-with-readable-numbers-for-singlestars', 'N64', 'Super Releasio 64 (with readable numbers, for singlestars)', '2021', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', 'Surreal 3D platforming with a focused goal and clearer UI.', 'Find specific stars in the distorted Releasio world.', 'A more "playable" version of the Releasio mod with visible numbers.', 'Super Releasio 64 (for singlestars) makes the chaotic "Toad-textured" world navigable for competitive players, allowing for a structured challenge within the madness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-releasio-64-3---retoaded', 'N64', 'Super Releasio 64 3 - Retoaded', '2022', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', 'Surreal 3D platforming with even more aggressive Toad themes.', 'Survive the most intense version of the Releasio universe yet.', 'The third installment of the bizarre Releasio trilogy.', 'Super Releasio 64 3 - Retoaded pushes the "Toad" aesthetic to its absolute limit. With updated textures and custom-warped music, it is the ultimate trial for fans of weird N64 mods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-spirits-japan', 'N64', 'Super Robot Spirits (Japan)', '1998', 'Fighting', 'Banpresto', '1', 'Anime Fighting', '2D fighting game with giant robots and mecha characters.', 'Defeat a roster of powerful robots to become the top pilot.', 'A high-quality mecha fighter exclusive to the Japanese market.', 'Super Robot Spirits (Japan) features iconic mechas in a technical 3D fighting environment. Master diverse movesets and enjoy the cinematic special attacks on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-64-japan', 'N64', 'Super Robot Taisen 64 (Japan)', '1999', 'Strategy', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with an epic mecha crossover story.', 'Command a fleet of giant robots to win the interstellar war.', 'A massive strategy RPG featuring legendary mecha anime series.', 'Super Robot Taisen 64 (Japan) is a landmark strategy title. Use the N64’s power to experience beautiful sprite work and deep tactical combat with your favorite mecha heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-silver-64', 'N64', 'Super Silver 64', '2021', 'Platformer', 'ROM Hack Community', '1', '3D Platformer', 'High-speed 3D platforming featuring Silver the Hedgehog.', 'Use psychokinesis to clear custom-built platforming levels.', 'A character mod bringing Silver''s futuristic style to Mario 64.', 'Super Silver 64 focuses on unique movement and psychokinetic abilities. Explore custom environments as the futuristic hedgehog in this creative N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-slide-64', 'N64', 'Super Slide 64', '2019', 'Platformer', 'ROM Hack Community', '1', 'Physics Challenge', 'High-speed technical sliding in a compilation of courses.', 'Master every custom slide to earn the title of "Slide King."', 'A dedicated mod pack focusing entirely on the slide mechanic.', 'Super Slide 64 is a dream for speedrunners. Test your reflexes on dozens of custom-built tracks designed to push the N64''s momentum physics to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-australia', 'N64', 'Super Smash Bros. (Australia)', '1999', 'Fighting', 'HAL Laboratory', '4', 'Platform Fighter', '2.5D crossover fighting with iconic Nintendo characters.', 'Knock your opponents off the stage to be the last one standing.', 'The rare Australian PAL version of the original Smash Bros.', 'Super Smash Bros. (Australia) brings the legendary 4-player combat to the PAL region. Experience the start of the franchise with tight controls and classic N64 charm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-europe-enfrde', 'N64', 'Super Smash Bros. (Europe) (En,Fr,De)', '1999', 'Fighting', 'HAL Laboratory', '4', 'Platform Fighter', '2.5D crossover fighting with multi-language support.', 'Defeat Mario, Link, and Pikachu in this revolutionary brawler.', 'The European release of the first game in the Smash Bros. series.', 'Super Smash Bros. (Europe) features the complete original roster and maps. Battle friends in one of the most influential and beloved fighting games on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-usa', 'N64', 'Super Smash Bros. (USA)', '1999', 'Fighting', 'HAL Laboratory', '4', 'Platform Fighter', '2.5D crossover fighting with a focus on competitive play.', 'Become the superstar champion by defeating the original roster.', 'The definitive North American release of the fighting masterpiece.', 'Super Smash Bros. (USA) changed gaming forever. With its unique "percentage" damage system and accessible controls, it remains a competitive staple and a must-play N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-19xxce', 'N64', 'Super Smash Bros. 19XXCE', '2020', 'Fighting', 'ROM Hack Community', '4', 'Competitive Mod', '2.5D crossover fighting with advanced technical features.', 'Compete in a high-fidelity version of Smash with modern tweaks.', 'A "Community Edition" (CE) mod for competitive Smash 64.', 'Super Smash Bros. 19XXCE offers refined menus, hitbox viewers, and tournament-ready features for the hardcore N64 community. It is the gold standard for high-level Smash 64 play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-19xxte', 'N64', 'Super Smash Bros. 19XXTE', '2020', 'Fighting', 'ROM Hack Community', '4', 'Training Mod', '2.5D crossover fighting with tournament-specific tools.', 'Master the original mechanics with improved performance.', 'A "Tournament Edition" (TE) of the classic Smash Bros game.', 'Super Smash Bros. 19XXTE is designed for the competitive scene. It includes quality-of-life improvements and bug fixes that ensure the fairest possible tournament experience on N64 hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-sonic-2-mod', 'N64', 'Super Smash Bros. Sonic 2 Mod', '2021', 'Fighting', 'ROM Hack Community', '4', 'Character Mod', '2.5D crossover fighting featuring a Sonic the Hedgehog skin.', 'Battle the Nintendo roster with a Sonic-themed visual overhaul.', 'A cosmetic mod that adds Sonic assets to the original Smash game.', 'Super Smash Bros. Sonic 2 Mod is a fun visual twist. Experience the classic Smash gameplay with Sonic''s look and feel, bringing the Blue Blur into the 64-bit arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-bros-sonic-mod', 'N64', 'Super Smash Bros. Sonic Mod', '2021', 'Fighting', 'ROM Hack Community', '4', 'Character Mod', '2.5D crossover fighting featuring Sonic character assets.', 'Defeat the Smash roster using a custom Sonic character model.', 'An early-era mod that swaps Mario for Sonic in Smash 64.', 'Super Smash Bros. Sonic Mod is a nostalgic fan project. It provides a unique "what if" scenario for N64 owners, merging the world''s most famous rivals in combat.');
