INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tails-64-revamped-sage-21-demo', 'N64', 'Tails 64 Revamped (SAGE ''21 DEMO)', '2021', 'Platformer', 'ROM Hack Community', '1', 'Character Mod', '3D platforming with Tails'' flight and tail-whip mechanics.', 'Explore custom levels and collect rings as Miles "Tails" Prower.', 'A high-quality revamped demo for Tails in the Mario 64 engine.', 'Tails 64 Revamped brings everyone''s favorite fox to the N64. Use Tails'' signature flight ability to discover secrets and explore levels from a brand-new vertical perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tamiya-racing-64-usa-proto', 'N64', 'Tamiya Racing 64 (USA) (Proto)', '1999', 'Racing', 'Tamiya / Imagineer', '2', 'RC Racing', 'Radio-controlled car racing with customizable Tamiya models.', 'Win RC races across creative, oversized environments.', 'An unreleased prototype for a Tamiya-licensed RC racer.', 'Tamiya Racing 64 (USA) (Proto) features miniature car action. Race through household settings and specialized tracks in this rare look at a planned N64 racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarzan-europe', 'N64', 'Tarzan (Europe)', '1999', 'Platformer', 'Eurocom', '1', 'Platform Adventure', '2.5D side-scrolling platformer with lush jungle visuals.', 'Navigate the jungle to stop Clayton and protect the gorillas.', 'The European release of the Disney-inspired jungle adventure.', 'Tarzan (Europe) captures the spirit of the animated movie. Swing through vines, slide down branches, and collect tokens in this vibrant and cinematic N64 platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarzan-france', 'N64', 'Tarzan (France)', '1999', 'Platformer', 'Eurocom', '1', 'Platform Adventure', '2.5D side-scrolling platformer with French localization.', 'Save the jungle and help Tarzan discover his origins.', 'The localized French version of the Disney action-platformer.', 'Tarzan (France) brings the epic journey of the Lord of the Jungle to French fans. Experience fluid animations and high-quality sound in this faithful movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarzan-germany', 'N64', 'Tarzan (Germany)', '1999', 'Platformer', 'Eurocom', '1', 'Platform Adventure', '2.5D side-scrolling platformer with German localization.', 'Master the jungle''s dangers to protect your family.', 'The localized German version of the Tarzan platformer.', 'Tarzan (Germany) offers the full jungle experience for German players. Swing, climb, and fight through beautifully rendered 3D environments on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarzan-usa', 'N64', 'Tarzan (USA)', '1999', 'Platformer', 'Eurocom', '1', 'Platform Adventure', '2.5D side-scrolling platformer with lush jungle visuals.', 'Experience the legend of Tarzan across multiple stages.', 'The North American release of the Disney action-platformer.', 'Tarzan (USA) is a visual treat on the N64. Revisit the events of the movie, play as both young and adult Tarzan, and enjoy the varied gameplay modes and bonus levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-express-europe-enfrdeesitnl', 'N64', 'Taz Express (Europe) (En,Fr,De,Es,It,Nl)', '2000', 'Platformer', 'Behaviour Interactive', '1', 'Platform Adventure', '3D puzzle-platforming featuring Taz the Tasmanian Devil.', 'Deliver fragile crates across dangerous landscapes.', 'A unique delivery-based puzzle game for the European market.', 'Taz Express (Europe) puts you in the shoes of a delivery devil. Manage weight and physics while navigating obstacles to ensure your cargo arrives in one piece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-express-usa-proto', 'N64', 'Taz Express (USA) (Proto)', '2000', 'Platformer', 'Behaviour Interactive', '1', 'Platform Adventure', '3D puzzle-platforming featuring Taz the Tasmanian Devil.', 'Complete the delivery missions in this unreleased build.', 'A rare North American prototype of the Taz delivery game.', 'Taz Express (USA) (Proto) showcases the unique puzzle mechanics developed for Taz. Navigate creative environments and solve physics-based problems in this rare N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('telefoot-soccer-2000-france', 'N64', 'Telefoot Soccer 2000 (France)', '2000', 'Sports', 'Silicon Dreams', '2', 'Soccer Simulation', 'Football simulation with French professional league focus.', 'Lead your soccer team to victory in the French championship.', 'A localized French soccer game featuring the Telefoot license.', 'Telefoot Soccer 2000 (France) offers authentic football action. Manage your team and master the pitch in this specialized sports title for the French N64 audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('termina-field', 'N64', 'Termina Field', '2021', 'Adventure', 'ROM Hack Community', '1', 'Exploration Hack', '3D exploration in a recreation of the Zelda world.', 'Explore the vast plains of Termina in the Mario 64 engine.', 'A custom level mod that recreates Termina Field from Majora''s Mask.', 'Termina Field is a nostalgic crossover for N64 fans. Explore a high-fidelity recreation of the iconic Zelda location using Mario''s movement, complete with custom music and assets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('termina-invasion', 'N64', 'Termina Invasion', '2022', 'Action', 'ROM Hack Community', '1', 'Action Platformer', '3D action-adventure featuring an invasion scenario.', 'Defend Termina from a mysterious and overwhelming threat.', 'A story-focused mod set in the world of Majora''s Mask.', 'Termina Invasion offers a unique take on the Zelda universe. Face off against invading forces and protect the citizens of Clock Town in this atmospheric and creative N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-64-japan', 'N64', 'Tetris 64 (Japan)', '1998', 'Puzzle', 'Bullet-Proof Software', '2', 'Falling Block Puzzle', 'Classic tile-matching puzzle game with a Japanese twist.', 'Clear rows of blocks to achieve a high score or defeat rivals.', 'A Japan-exclusive Tetris game featuring unique modes.', 'Tetris 64 (Japan) is a classic with a twist. Supporting the Bio-Sensor to react to your heart rate, it offers one of the most unique ways to experience the world''s most famous puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetrisphere-europe', 'N64', 'Tetrisphere (Europe)', '1997', 'Puzzle', 'H2O Entertainment', '1', '3D Puzzle', '3D spherical puzzle-solving with explosive chain reactions.', 'Clear layers of a sphere to reveal the core and free robots.', 'A unique 3D take on the puzzle genre with a techno vibe.', 'Tetrisphere (Europe) is a visually stunning puzzle game that defies tradition. Match shapes on a revolving sphere and use powerful combos to blast through layers in this atmospheric N64 cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetrisphere-usa', 'N64', 'Tetrisphere (USA)', '1997', 'Puzzle', 'H2O Entertainment', '1', '3D Puzzle', '3D spherical puzzle-solving with explosive chain reactions.', 'Master the sphere-clearing mechanics across various modes.', 'The North American version of the innovative 3D puzzler.', 'Tetrisphere (USA) features an amazing electronic soundtrack and unique "Lines" and "Rescue" modes. It stands as one of the most creative and addictive puzzle games on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tg-rally-2-europe', 'N64', 'TG Rally 2 (Europe)', '1999', 'Racing', 'Tantalus Interactive', '2', 'Rally Racing', 'Off-road rally racing with realistic physics and damage.', 'Win the world championship by mastering mud, snow, and gravel.', 'The European version of the high-octane Top Gear Rally sequel.', 'TG Rally 2 (Europe) brings professional rally racing to your console. Featuring a deep car editor and realistic weather effects, it challenges players to master every curve in this technical N64 racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-dark-world', 'N64', 'The Dark World', '2021', 'Adventure', 'ROM Hack Community', '1', 'Dark Adventure', '3D platforming in a dark, atmospheric custom world.', 'Navigate the shadows to find the hidden Power Stars.', 'A moody and difficult ROM hack for the Mario 64 engine.', 'The Dark World is a challenging modification that emphasizes atmosphere. Explore haunting custom levels with unique lighting and textures in this dark take on 3D platforming for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-death-of-mario-v11', 'N64', 'The Death of Mario (v1.1)', '2019', 'Platformer', 'ROM Hack Community', '1', 'Horror Platformer', '3D platforming with survival and horror-lite elements.', 'Uncover the mystery behind Mario''s disappearance in this sequel.', 'A story-driven ROM hack that explores a darker narrative.', 'The Death of Mario (v1.1) is an intriguing fan-made sequel. Navigate through eerie worlds and solve environmental puzzles to discover the truth in this unique N64 narrative project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-disaster-of-brainrot-2:-walters-white-wet-wild-adventure', 'N64', 'The Disaster of Brainrot 2: Walter''s White Wet Wild Adventure', '2023', 'Platformer', 'ROM Hack Community', '1', 'Meme Platformer', '3D platforming with chaotic memes and surreal humor.', 'Survive Walter''s wild adventure across "brainrot" levels.', 'A comedy-focused mod packed with internet culture references.', 'The Disaster of Brainrot 2 is a high-energy, humorous N64 mod. Experience bizarre levels, custom sounds, and surreal challenges in this intentionally wild and funny Mario 64 hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-fate-of-the-bombiwa', 'N64', 'The Fate of the Bombiwa', '2021', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D platforming with a focus on custom story and lore.', 'Save the Bombiwa tribe by recovering their ancient artifacts.', 'A creative adventure hack with unique NPCs and world-building.', 'The Fate of the Bombiwa offers a fresh narrative for N64 fans. Explore vibrant new worlds and interact with custom characters in this beautifully designed and story-heavy modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-helix-blade-demo', 'N64', 'The Helix Blade Demo', '2022', 'Action', 'ROM Hack Community', '1', 'Action Demo', '3D action-adventure with a focus on sword combat mechanics.', 'Master the Helix Blade to defeat a rising ancient evil.', 'A demo of an ambitious project featuring custom combat logic.', 'The Helix Blade Demo showcases impressive new gameplay for the N64. Experience advanced sword mechanics and custom animations in this promising action-adventure fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-hidden-temple', 'N64', 'The Hidden Temple', '2020', 'Adventure', 'ROM Hack Community', '1', 'Exploration Adventure', 'Exploration-based 3D platforming in an ancient jungle temple.', 'Solve the riddles of the temple to claim the legendary star.', 'A custom level mod featuring a large, interconnected temple.', 'The Hidden Temple challenges players with non-linear exploration. Navigate through traps and ancient machinery to find all the secrets hidden within this N64 temple world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-hole-to-hyrule', 'N64', 'The Hole to Hyrule', '2021', 'Adventure', 'ROM Hack Community', '1', 'Zelda Crossover', '3D platforming crossover set in the Zelda universe.', 'Find a way into the subterranean world of Hyrule.', 'A portal-themed mod connecting Mario''s world to Zelda''s.', 'The Hole to Hyrule is a nostalgic crossover for N64 fans. Explore deep caverns and solve puzzles that bridge the gap between the Mushroom Kingdom and the land of Link.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-inner-mounting-stars', 'N64', 'The Inner Mounting Stars', '2022', 'Platformer', 'ROM Hack Community', '1', 'Challenge Platformer', 'High-difficulty 3D platforming in abstract, vertical worlds.', 'Climb to the highest peaks of the stars without falling.', 'A technical "climbing" hack for Super Mario 64.', 'The Inner Mounting Stars focuses on verticality and precision. Master difficult wall-jumps and tight platforming in this beautifully rendered and challenging N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-junuary-project', 'N64', 'The Junuary Project', '2022', 'Platformer', 'ROM Hack Community', '1', 'Experimental Platformer', '3D platforming in a winter-themed, serene custom world.', 'Explore the snowy landscapes of Junuary to find hidden stars.', 'A peaceful and artistic winter hack with custom textures.', 'The Junuary Project offers a relaxing and atmospheric N64 experience. Wander through snowy forests and icy caves in this visually stunning and creative fan-made adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-legend-of-mario-64', 'N64', 'The Legend of Mario 64', '2021', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D action-adventure with Zelda-inspired world design.', 'Save the Princess by navigating through dungeons and fields.', 'A total conversion mod blending Mario 64 with Zelda logic.', 'The Legend of Mario 64 is the ultimate crossover. Explore a world designed with Zelda''s structure but using Mario''s movement, featuring custom dungeons and equipment on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-legend-of-zelda-ocarina-of-time-stamina-bar', 'N64', 'The Legend of Zelda Ocarina of Time STAMINA BAR', '2020', 'Action', 'ROM Hack Community', '1', 'Gameplay Modification', 'Action-adventure with a realistic physical limit system.', 'Manage your stamina while exploring the lands of Hyrule.', 'A gameplay tweak for Ocarina of Time adding a stamina bar.', 'The Legend of Zelda Ocarina of Time STAMINA BAR adds a layer of realism to the classic. Manage Link''s energy while running, climbing, and fighting in this survival-lite N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-legend-of-zelda:-nightmare', 'N64', 'The Legend of Zelda: Nightmare', '2021', 'Horror', 'ROM Hack Community', '1', 'Psychological Horror', 'Survival horror action-adventure set in a corrupted Hyrule.', 'Survive the nightmare and find a way to break the curse.', 'A dark and terrifying reimagining of Ocarina of Time.', 'The Legend of Zelda: Nightmare is a horror-themed Zelda mod. Experience a decaying world, custom-designed enemies, and a haunting soundtrack that turns Hyrule into a land of fear on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-magical-lands', 'N64', 'The Magical Lands', '2020', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D platforming across themed "magical" custom environments.', 'Discover the secrets of the magical lands and recover the stars.', 'A classic-style ROM hack with diverse and imaginative levels.', 'The Magical Lands provides a variety of themed worlds, from enchanted forests to mystical ruins, each filled with unique puzzles and platforming challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-movie-sonic-project', 'N64', 'The Movie Sonic Project', '2022', 'Action', 'ROM Hack Community', '1', 'Cinematic Platformer', '3D platforming featuring the cinematic "Movie Sonic" model.', 'Run through custom-built zones as the big-screen version of Sonic.', 'A character swap mod featuring the Sonic Movie design.', 'The Movie Sonic Project brings the modern look of Sonic to the N64. Enjoy high-speed platforming with custom animations and textures based on the hit theatrical film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-octember-project', 'N64', 'The Octember Project', '2021', 'Adventure', 'ROM Hack Community', '1', 'Story Adventure', '3D platforming in an autumn-themed, atmospheric custom world.', 'Explore the orange and gold landscapes of Octember.', 'A visually cozy hack centered on autumn colors and peace.', 'The Octember Project is an artistic exploration mod. Navigate through falling leaves and warm lighting in this uniquely themed and beautifully crafted N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-soul-of-legends', 'N64', 'The Soul of Legends', '2021', 'Adventure', 'ROM Hack Community', '1', 'Legendary Adventure', '3D platforming with a focus on mythical story and trials.', 'Collect the souls of ancient legends to restore the world.', 'A lore-heavy ROM hack with unique characters and trials.', 'The Soul of Legends offers a deep story-driven experience for N64 fans. Complete spiritual trials and explore mythical realms in this ambitious and creative fan-made sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-super-mario-bros-super-show-64-v11', 'N64', 'The Super Mario Bros. Super Show 64 (v1.1)', '2021', 'Platformer', 'ROM Hack Community', '1', 'Crossover Platformer', '3D platforming based on the classic 1980s animated show.', 'Experience the cartoon world with custom voices and art style.', 'A nostalgic mod based on the Super Mario Bros. Super Show.', 'The Super Mario Bros. Super Show 64 (v1.1) captures the charm of the TV series. Featuring the iconic voices of Lou Albano and Danny Wells, it’s a trip down memory lane for N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thousand-year-door-64', 'N64', 'Thousand-Year Door 64', '2022', 'RPG', 'ROM Hack Community', '1', 'Action RPG', '3D platforming inspired by the Paper Mario sequel.', 'Explore custom levels with the aesthetic of the GameCube classic.', 'A visual and gameplay mod inspired by The Thousand-Year Door.', 'Thousand-Year Door 64 brings the style of the RPG sequel to the N64 platformer. Navigate creative stages with a unique flat-styled look and RPG-inspired elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('through-the-ages-v11', 'N64', 'Through The Ages v1.1', '2021', 'Adventure', 'ROM Hack Community', '1', 'Time-Based Adventure', '3D platforming that evolves through different graphical eras.', 'Travel through time to see how the game world changes.', 'A conceptual hack featuring evolving textures and level design.', 'Through The Ages v1.1 is a unique journey through gaming history. Experience the world as it transitions through different visual styles, offering a fresh take on the N64 engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiggers-honey-hunt-europe-enfrdeesitnlda', 'N64', 'Tigger''s Honey Hunt (Europe) (En,Fr,De,Es,It,Nl,Da)', '2000', 'Platformer', 'Digital Eclipse', '1', 'Platform Adventure', '3D exploration and puzzle-solving in the 100 Acre Wood.', 'Help Tigger find honey for Pooh''s party across various levels.', 'A charming and family-friendly adventure for the European market.', 'Tigger''s Honey Hunt (Europe) captures the magic of Winnie the Pooh. Play as Tigger, mastering his "bouncy" movement through mini-games and exploration in this colorful N64 title.');
