INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-and-jerry-in-fists-of-furry-europe-enfrdeesitnl', 'N64', 'Tom and Jerry in Fists of Furry (Europe) (En,Fr,De,Es,It,Nl)', '2000', 'Fighting', 'Vis Interactive', '4', 'Arena Fighter', '3D arena fighting game with cartoon-style combat.', 'Defeat Tom or Jerry in a variety of household locations.', 'The European version of the slapstick fighting game.', 'Tom and Jerry in Fists of Furry (Europe) brings the classic cartoon rivalry to life. Use frying pans, chairs, and other household objects to knock out your opponent in this fun N64 brawler.');
