INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-rainbow-six-europe', 'N64', 'Tom Clancy''s Rainbow Six (Europe)', '1999', 'Tactical', 'Saffire', '4', 'Tactical Shooter', 'Tactical first-person shooter with mission planning and stealth.', 'Lead an elite anti-terrorist unit to neutralize global threats.', 'The European release of the realistic tactical shooter.', 'Tom Clancy''s Rainbow Six (Europe) emphasizes strategy over speed. Plan your missions, choose your equipment, and execute precise tactical strikes in this high-stakes N64 simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-rainbow-six-france', 'N64', 'Tom Clancy''s Rainbow Six (France)', '1999', 'Tactical', 'Saffire', '4', 'Tactical Shooter', 'Tactical first-person shooter with French localization.', 'Save hostages and stop the terrorists across diverse missions.', 'The localized French version of the tactical shooter.', 'Tom Clancy''s Rainbow Six (France) offers the full tactical experience in French. Experience the tense atmosphere of international counter-terrorism on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-rainbow-six-germany', 'N64', 'Tom Clancy''s Rainbow Six (Germany)', '1999', 'Tactical', 'Saffire', '4', 'Tactical Shooter', 'Tactical first-person shooter with German localization.', 'Prevent global catastrophes with careful tactical planning.', 'The localized German version of the tactical shooter.', 'Tom Clancy''s Rainbow Six (Germany) brings the realism of Rainbow Six to German fans. Manage your squad and master the art of the tactical breach in this challenging title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-rainbow-six-usa', 'N64', 'Tom Clancy''s Rainbow Six (USA)', '1999', 'Tactical', 'Saffire', '4', 'Tactical Shooter', 'Tactical first-person shooter with mission planning and stealth.', 'Complete the global campaign to stop a biological threat.', 'The North American version of the acclaimed tactical FPS.', 'Tom Clancy''s Rainbow Six (USA) set the standard for tactical shooters on consoles. With a heavy focus on realism and planning, it offers a deep and rewarding experience for N64 players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tommy-thunder-usa-proto', 'N64', 'Tommy Thunder (USA) (Proto)', '1997', 'Action', 'Scavenger', '1', 'Action Adventure', '3D platforming with a superhero theme and gadgets.', 'Use Tommy''s thunder powers to save the city from villains.', 'A rare, unreleased prototype of a superhero action game.', 'Tommy Thunder (USA) (Proto) provides a look at a cancelled N64 project. Explore early levels and use lightning-based abilities in this fascinating piece of gaming history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tonic-trouble-europe-enfrdeesit', 'N64', 'Tonic Trouble (Europe) (En,Fr,De,Es,It)', '1999', 'Platformer', 'Infogrames', '1', '3D Platformer', '3D platforming with a surreal art style and fluid movement.', 'Help Ed save the world from the effects of the mysterious "Can."', 'A creative and humorous platformer from Ubisoft for Europe.', 'Tonic Trouble (Europe) features the quirky protagonist Ed in a vibrant, 3D world. Solve puzzles and use wacky power-ups to fix the mess you''ve made in this imaginative N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tonic-trouble-usa-rev-a', 'N64', 'Tonic Trouble (USA) (Rev A)', '1999', 'Platformer', 'Infogrames', '1', '3D Platformer', '3D platforming with refined mechanics and bug fixes.', 'Navigate the chaotic world and defeat the evil Grogh.', 'An updated revision of the North American platformer.', 'Tonic Trouble (USA) (Rev A) offers the most polished version of Ed''s adventure. Enjoy the unique art style and creative level design with improved performance for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-usa', 'N64', 'Tony Hawk''s Pro Skater (USA)', '2000', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Skateboarding simulation with combo-based trick scoring.', 'Complete objectives and achieve high scores across urban levels.', 'The legendary first entry in the Tony Hawk skating series.', 'Tony Hawk''s Pro Skater (USA) redefined extreme sports games. Master the kickflip, grind through iconic warehouses, and collect S-K-A-T-E letters in the game that started a global phenomenon on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-usa-rev-a', 'N64', 'Tony Hawk''s Pro Skater (USA) (Rev A)', '2000', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Skateboarding simulation with refined physics and bug fixes.', 'Master every park and unlock secret skaters with improved stability.', 'An updated revision of the original North American skating classic.', 'Tony Hawk''s Pro Skater (USA) (Rev A) provides the smoothest version of the first game. Enjoy the iconic punk-rock soundtrack and tight controls with minor technical polish for a perfect N64 session.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-2-europe', 'N64', 'Tony Hawk''s Pro Skater 2 (Europe)', '2001', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Skateboarding simulation with an expanded move set and levels.', 'Build your skater''s stats and win professional competitions.', 'The acclaimed sequel featuring larger levels and more tricks.', 'Tony Hawk''s Pro Skater 2 (Europe) takes the series to new heights. With the addition of the "Manual" mechanic for longer combos and a deep career mode, it remains a gold standard for N64 sports titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-2-usa', 'N64', 'Tony Hawk''s Pro Skater 2 (USA)', '2001', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Skateboarding simulation with an expanded move set and levels.', 'Reach 100% completion in career mode and find all secret tapes.', 'The definitive North American release of the iconic skating sequel.', 'Tony Hawk''s Pro Skater 2 (USA) features a legendary roster including Tony Hawk and Rodney Mullen. Explore massive levels like Hangar and School II while pulling off high-scoring combos in this N64 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-3-usa', 'N64', 'Tony Hawk''s Pro Skater 3 (USA)', '2002', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Skateboarding simulation with high-fidelity textures and fast gameplay.', 'Complete pro goals and achieve massive scores in new locations.', 'The third installment of the series, optimized for the N64 hardware.', 'Tony Hawk''s Pro Skater 3 (USA) is an impressive late-era N64 release. Experience smooth 60fps performance on several tracks and enjoy the refined trick system that includes the Revert for ultimate combo chaining.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-skateboarding-europe', 'N64', 'Tony Hawk''s Skateboarding (Europe)', '2000', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Skateboarding simulation with combo-based trick scoring.', 'Rise through the ranks of professional skating in Europe.', 'The European edition of the first THPS, renamed for the region.', 'Tony Hawk''s Skateboarding (Europe) offers the exact same high-energy gameplay as the US version. Shred through realistic environments and master the trick system that made Tony Hawk a household name.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toon-panic-japan-proto', 'N64', 'Toon Panic (Japan) (Proto)', '1999', 'Action', 'Ultra', '1', 'Action Puzzle', '3D party-action game with unique character abilities.', 'Defeat opponents in wacky arena-based combat and trials.', 'A rare, unreleased Japanese prototype from the makers of Goemon.', 'Toon Panic (Japan) (Proto) is a fascinating look at a cancelled Konami project. Featuring vibrant "toon" aesthetics and creative arena combat, it stands as a unique piece of N64 development history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-hyper-bike-europe', 'N64', 'Top Gear Hyper-Bike (Europe)', '2000', 'Racing', 'Snowblind Studios', '2', 'Motorcycle Racing', 'High-speed motorcycle racing across diverse terrains.', 'Win championships and upgrade your bikes for maximum speed.', 'A motorcycle-focused spin-off of the Top Gear racing franchise.', 'Top Gear Hyper-Bike (Europe) offers adrenaline-pumping racing on two wheels. Navigate narrow tracks and master the physics of motocross and street bikes in this high-speed N64 challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-hyper-bike-japan', 'N64', 'Top Gear Hyper-Bike (Japan)', '2000', 'Racing', 'Snowblind Studios', '2', 'Motorcycle Racing', 'High-speed motorcycle racing across diverse terrains.', 'Become the top rider in the Japanese motorcycle circuit.', 'The Japanese version of the high-speed motorcycle racer.', 'Top Gear Hyper-Bike (Japan) features intense racing and technical track designs. Choose from a variety of bikes and master the drifting mechanics to dominate the competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-hyper-bike-usa', 'N64', 'Top Gear Hyper-Bike (USA)', '2000', 'Racing', 'Snowblind Studios', '2', 'Motorcycle Racing', 'High-speed motorcycle racing across diverse terrains.', 'Conquer the hyper-bike tournament and unlock secret vehicles.', 'The North American release of the Top Gear motorcycle title.', 'Top Gear Hyper-Bike (USA) is known for its fast pace and varied tracks. From desert dunes to city streets, experience the thrill of high-speed bike racing with tight N64 controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-overdrive-europe', 'N64', 'Top Gear Overdrive (Europe)', '2000', 'Racing', 'Snowblind Studios', '2', 'Arcade Racing', 'Arcade-style racing with car upgrades and nitrous boosts.', 'Finish first in every race to earn cash and buy faster cars.', 'A stylish, fast-paced racer with a heavy focus on customization.', 'Top Gear Overdrive (Europe) features a killer soundtrack and intense racing action. Customize your car''s engine, tires, and paint to stay ahead of the pack in this colorful N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-overdrive-japan', 'N64', 'Top Gear Overdrive (Japan)', '2000', 'Racing', 'Snowblind Studios', '2', 'Arcade Racing', 'Arcade-style racing with car upgrades and nitrous boosts.', 'Master the tracks and outrun your rivals in the Japanese circuit.', 'The Japanese localized version of the stylish arcade racer.', 'Top Gear Overdrive (Japan) delivers the same high-speed thrills with localized menus. Experience the sense of speed and aggressive AI that defined this late-90s racing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-overdrive-usa', 'N64', 'Top Gear Overdrive (USA)', '2000', 'Racing', 'Snowblind Studios', '2', 'Arcade Racing', 'Arcade-style racing with car upgrades and nitrous boosts.', 'Unlock all hidden cars and win the World Tour championship.', 'The North American release of the high-octane Top Gear racer.', 'Top Gear Overdrive (USA) is an arcade fan''s dream. With hidden shortcuts, weather effects, and a rewarding upgrade system, it offers hours of high-speed entertainment on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-rally-europe', 'N64', 'Top Gear Rally (Europe)', '1997', 'Racing', 'Boss Game Studios', '4', 'Rally Racing', 'Rally racing simulation with realistic weather and terrain.', 'Master the art of drifting on mud, snow, and gravel.', 'The original N64 rally game that set a new standard for physics.', 'Top Gear Rally (Europe) is famous for its customizable car skins and realistic handling. Experience the challenge of professional rally racing across beautifully rendered seasonal tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-rally-japan', 'N64', 'Top Gear Rally (Japan)', '1997', 'Racing', 'Boss Game Studios', '4', 'Rally Racing', 'Rally racing simulation with realistic weather and terrain.', 'Win the seasonal championships in the Japanese rally circuit.', 'The Japanese version of the acclaimed N64 rally simulator.', 'Top Gear Rally (Japan) features the same deep physics and car editing tools. Navigate difficult hairpins and changing road surfaces to prove you are the ultimate rally driver.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-rally-usa', 'N64', 'Top Gear Rally (USA)', '1997', 'Racing', 'Boss Game Studios', '4', 'Rally Racing', 'Rally racing simulation with realistic weather and terrain.', 'Navigate every stage and master the car-painting tools.', 'The North American release of the groundbreaking rally racer.', 'Top Gear Rally (USA) was a technical marvel at launch. With its impressive physics engine and car customization, it remains a favorite for N64 racing enthusiasts looking for a challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-rally-2-europe', 'N64', 'Top Gear Rally 2 (Europe)', '1999', 'Racing', 'Boss Game Studios', '4', 'Rally Racing', 'Off-road rally racing with car damage and realistic physics.', 'Win the global rally circuit and manage your car''s repairs.', 'The feature-rich sequel to the original N64 rally hit.', 'Top Gear Rally 2 (Europe) introduces a sophisticated damage system and randomly generated tracks. Experience the evolution of rally racing with more cars and deeper simulation elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-rally-2-japan', 'N64', 'Top Gear Rally 2 (Japan)', '1999', 'Racing', 'Boss Game Studios', '4', 'Rally Racing', 'Off-road rally racing with car damage and realistic physics.', 'Become the rally world champion in the Japanese league.', 'The Japanese version of the expanded rally racing sequel.', 'Top Gear Rally 2 (Japan) offers a deep career mode and technical driving mechanics. Manage your resources and drive carefully to avoid terminal damage in this realistic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-rally-2-usa', 'N64', 'Top Gear Rally 2 (USA)', '1999', 'Racing', 'Boss Game Studios', '4', 'Rally Racing', 'Off-road rally racing with car damage and realistic physics.', 'Conquer the most difficult terrains and unlock legendary rally cars.', 'The North American release of the improved rally simulation.', 'Top Gear Rally 2 (USA) is a deep, rewarding racing game. With its focus on car maintenance and technical driving, it provides one of the most realistic off-road experiences on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('totsugeki-64', 'N64', 'Totsugeki 64', '1999', 'Fighting', 'A2M', '2', 'Anime Fighting', '3D platforming with custom character models and movement.', 'Navigate a variety of experimental levels to collect stars.', 'A creative technical mod for the Super Mario 64 engine.', 'Totsugeki 64 is a unique N64 mod that showcases custom character assets and physics. Explore imaginative levels that push the boundaries of what the classic engine can do.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---buzz-leclair-a-la-rescousse!-france', 'N64', 'Toy Story 2 - Buzz l''Eclair a la Rescousse! (France)', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D Platform Adventure', '3D action-platforming with movie-themed missions.', 'Help Buzz rescue Woody and find all the Pizza Planet tokens.', 'The French localized version of the Disney/Pixar hit.', 'Toy Story 2 - Buzz l''Eclair a la Rescousse! brings the movie magic to France. Explore Andy''s house, the toy store, and the airport in this polished 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---buzz-lightyear-to-the-rescue!-europe', 'N64', 'Toy Story 2 - Buzz Lightyear to the Rescue! (Europe)', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D Platform Adventure', '3D action-platforming with movie-themed missions.', 'Navigate oversized environments to save Woody from the collector.', 'The European multi-language release of the Buzz Lightyear game.', 'Toy Story 2 - Buzz Lightyear to the Rescue! (Europe) is a faithful adaptation of the film. Use Buzz''s laser and wings to complete puzzles and defeat bosses in this high-quality platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---buzz-lightyear-to-the-rescue!-usa', 'N64', 'Toy Story 2 - Buzz Lightyear to the Rescue! (USA)', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D Platform Adventure', '3D action-platforming with movie-themed missions.', 'Collect all tokens and defeat the Evil Emperor Zurg.', 'The North American release of the acclaimed movie tie-in.', 'Toy Story 2 - Buzz Lightyear to the Rescue! (USA) is widely considered one of the best licensed games on N64. Explore massive 3D worlds from a toy''s perspective in this nostalgic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---buzz-lightyear-to-the-rescue!-usa-rev-a', 'N64', 'Toy Story 2 - Buzz Lightyear to the Rescue! (USA) (Rev A)', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D Platform Adventure', '3D action-platforming with bug fixes and stability updates.', 'Complete the rescue mission with improved game performance.', 'An updated revision of the North American Toy Story 2 game.', 'Toy Story 2 - Buzz Lightyear to the Rescue! (USA) (Rev A) provides a more stable experience. Enjoy the cinematic music and diverse levels with minor technical improvements for the best N64 playthrough.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---captain-buzz-lightyear-auf-rettungsmission!-germany', 'N64', 'Toy Story 2 - Captain Buzz Lightyear auf Rettungsmission! (Germany)', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D Platform Adventure', '3D action-platforming with German localization.', 'Rescue Woody and defeat the Al''s Toy Barn boss.', 'The localized German version of the Buzz Lightyear adventure.', 'Toy Story 2 - Captain Buzz Lightyear auf Rettungsmission! (Germany) allows German fans to enjoy the full narrative of the film. Explore detailed 3D environments and use Buzz''s gadgets to save the day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---captain-buzz-lightyear-auf-rettungsmission!-germany-rev-a', 'N64', 'Toy Story 2 - Captain Buzz Lightyear auf Rettungsmission! (Germany) (Rev A)', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D Platform Adventure', '3D action-platforming with German text and stability fixes.', 'Experience the mission with the most polished German build.', 'An updated German revision of the Toy Story 2 adventure.', 'Toy Story 2 - Captain Buzz Lightyear auf Rettungsmission! (Germany) (Rev A) offers the final polished version for the German market, ensuring smooth gameplay through the movie-inspired worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('transformers---beast-wars-metals-64-japan', 'N64', 'Transformers - Beast Wars Metals 64 (Japan)', '1999', 'Fighting', 'TOSE', '2', 'Anime Fighting', '3D arena fighting game with transforming mecha.', 'Win the Beast Wars tournament as your favorite Transformer.', 'The Japanese version of the Beast Wars fighting game.', 'Transformers - Beast Wars Metals 64 (Japan) features characters from the hit CGI series. Master the transformation mechanics to switch between animal and robot forms during intense N64 battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('transformers---beast-wars-transmetals-usa', 'N64', 'Transformers - Beast Wars Transmetals (USA)', '1999', 'Fighting', 'TOSE', '2', 'Anime Fighting', '3D arena fighting game with transforming mecha.', 'Defeat the Predacons and save the future in the Transmetals war.', 'The North American release of the Transformers brawler.', 'Transformers - Beast Wars Transmetals (USA) offers unique combat based on the popular TV show. Choose your side and utilize flight and ground modes to dominate your rivals in 3D arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('transparent-mario', 'N64', 'Transparent Mario', '2020', 'Platformer', 'ROM Hack Community', '1', 'Meme Platformer', '3D platforming with a custom "Invisible" effect on Mario.', 'Complete levels while seeing through the main character.', 'A technical visual mod for the Super Mario 64 engine.', 'Transparent Mario is a unique experiment in N64 modding. Navigate through the game''s iconic levels with a ghost-like Mario, offering a different visual perspective on the classic platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('traumatic-tick-tock-tower', 'N64', 'Traumatic Tick Tock Tower', '2021', 'Platformer', 'ROM Hack Community', '1', 'Horror Platformer', '3D platforming with a high-difficulty, horror-themed clock tower.', 'Survive the shifting gears and traps to reach the top.', 'A challenging "Kaizo-lite" mod set in a terrifying clock tower.', 'Traumatic Tick Tock Tower is designed to test your patience and skill. Navigate a dark and dangerous version of Mario''s clock-themed level, filled with frame-perfect jumps and traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tribal-tropics', 'N64', 'Tribal Tropics', '2020', 'Platformer', 'Kaze Emanuar', '1', '3D Platformer', '3D platforming in a lush, jungle-themed custom world.', 'Navigate through tropical hazards and ancient ruins to find stars.', 'A vibrant, island-themed hack with a focus on dense environments.', 'Tribal Tropics brings a tropical vibe to the N64. Explore thick jungles and tribal villages in this beautifully textured and atmospheric platforming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trip-the-sungazer-64', 'N64', 'Trip The Sungazer 64', '2022', 'Platformer', 'Kaze Emanuar', '1', '3D Platformer', '3D platforming featuring a custom "Sungazer" character.', 'Explore the world of Mario 64 with a unique lizard protagonist.', 'A creative character mod featuring Trip the Sungazer.', 'Trip The Sungazer 64 introduces a new hero to the N64. Enjoy custom animations and a unique character model in this imaginative modification of the classic platforming engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trip-the-sungazer-64-armored', 'N64', 'Trip The Sungazer 64 (Armored)', '2022', 'Platformer', 'Kaze Emanuar', '1', 'Challenge Platformer', '3D platforming featuring an armored variant of the Sungazer.', 'Navigate through dangerous custom levels with a protective suit.', 'A character mod featuring the armored version of Trip.', 'Trip The Sungazer 64 (Armored) offers a cool visual twist on the character. Explore the Mushroom Kingdom with a sleek armored look and custom assets in this fun N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('triple-play-2000-usa', 'N64', 'Triple Play 2000 (USA)', '2000', 'Sports', 'EA Canada', '2', 'Baseball Simulation', 'Realistic baseball simulation with MLB licensing and rosters.', 'Win the World Series and master the art of pitching and batting.', 'A feature-rich baseball title for the 1999-2000 season.', 'Triple Play 2000 (USA) brings professional baseball to the N64. Featuring 3D scanned players and play-by-play commentary, it offers a deep and authentic MLB experience with multiple gameplay modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsumi-to-batsu---hoshi-no-keishousha-japan', 'N64', 'Tsumi to Batsu - Hoshi no Keishousha (Japan)', '2000', 'Shooter', 'Treasure', '1', 'Run and Gun Shooter', 'High-speed rail-shooter with intense melee and projectile combat.', 'Defeat the alien threats to protect the future of Earth.', 'The original Japanese release of the legendary Sin and Punishment.', 'Tsumi to Batsu (Japan) is a masterpiece of N64 action. Experience the cinematic storytelling and frantic gameplay of Saki and Airan in this cult classic developed by Treasure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-europe', 'N64', 'Turok - Dinosaur Hunter (Europe)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with platforming and prehistoric themes.', 'Find the pieces of the Chronoscepter and defeat the Campaigner.', 'The European release of the groundbreaking dinosaur shooter.', 'Turok - Dinosaur Hunter (Europe) redefined the FPS genre on consoles. Explore vast, fog-filled jungles, battle primitive warriors, and take down massive dinosaurs with futuristic weaponry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-europe-rev-a', 'N64', 'Turok - Dinosaur Hunter (Europe) (Rev A)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with refined performance and bug fixes.', 'Navigate the Lost Land and master the primitive arsenal.', 'An updated revision of the European Turok release.', 'Turok - Dinosaur Hunter (Europe) (Rev A) offers improved stability over the launch version. Enjoy the same high-intensity action with optimized performance for the PAL Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-europe-rev-b', 'N64', 'Turok - Dinosaur Hunter (Europe) (Rev B)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with final technical polish and logic fixes.', 'Recover the ancient artifacts and survive the prehistoric hunt.', 'The final technical revision for the European Turok release.', 'Turok - Dinosaur Hunter (Europe) (Rev B) provides the most polished version of the original adventure. Experience Tal''Set''s journey with corrected asset behavior and smoother gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-germany', 'N64', 'Turok - Dinosaur Hunter (Germany)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with localized German text and censored enemies.', 'Stop the evil forces in this specialized German version.', 'The localized German release, featuring robot enemies instead of humans.', 'Turok - Dinosaur Hunter (Germany) offers the classic Turok experience tailored for the German market. Battle robotic foes through the jungles of the Lost Land in this unique regional edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-germany-rev-a', 'N64', 'Turok - Dinosaur Hunter (Germany) (Rev A)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with German localization and bug fixes.', 'Master the weapons of the Lost Land in this updated German build.', 'A refined revision of the German-localized Turok.', 'Turok - Dinosaur Hunter (Germany) (Rev A) includes technical improvements while maintaining the specific regional edits that make this version of the dinosaur hunter legendary.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-germany-rev-b', 'N64', 'Turok - Dinosaur Hunter (Germany) (Rev B)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with final German technical updates.', 'Use the Chronoscepter to save the world in this polished build.', 'The final revision of the German-localized Turok adventure.', 'Turok - Dinosaur Hunter (Germany) (Rev B) is the most stable and refined version of the German release, offering optimized performance and final logic fixes for N64 players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-usa', 'N64', 'Turok - Dinosaur Hunter (USA)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with platforming and prehistoric themes.', 'Traverse the Lost Land to stop the Campaigner''s plan.', 'The North American release of the iconic FPS title.', 'Turok - Dinosaur Hunter (USA) is a landmark N64 game. Featuring a massive arsenal and open-ended level design, it set the standard for 3D exploration and combat in a prehistoric world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-usa-rev-a', 'N64', 'Turok - Dinosaur Hunter (USA) (Rev A)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with refined performance and bug fixes.', 'Hunt dinosaurs and master the futuristic weaponry.', 'An updated revision of the North American Turok release.', 'Turok - Dinosaur Hunter (USA) (Rev A) improves on the original launch with better framerate stability and minor glitch corrections for a superior hunting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---dinosaur-hunter-usa-rev-b', 'N64', 'Turok - Dinosaur Hunter (USA) (Rev B)', '1997', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with final technical polish and logic fixes.', 'Prevent the collapse of time and space in the Lost Land.', 'The final technical revision of the North American Turok.', 'Turok - Dinosaur Hunter (USA) (Rev B) is the definitive version of the first Turok. Experience the smoothest gameplay and most stable environment for Tal''Set''s epic journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---legenden-des-verlorenen-landes-germany', 'N64', 'Turok - Legenden des Verlorenen Landes (Germany)', '1998', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with localized German text and voice acting.', 'Stop the Primagen''s plan to destroy the universe.', 'The German version of Turok 2, featuring regional censorship.', 'Turok - Legenden des Verlorenen Landes (Germany) is the localized title for Seeds of Evil. Experience the massive campaign with robot enemies and German text on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---rage-wars-europe', 'N64', 'Turok - Rage Wars (Europe)', '1999', 'Shooter', 'Acclaim Studios Austin', '4', 'Arena Shooter', 'Arena-based multiplayer first-person shooter with various modes.', 'Defeat your rivals in a series of gladiatorial combat trials.', 'A multiplayer-focused spin-off of the Turok series for Europe.', 'Turok - Rage Wars (Europe) focuses on fast-paced arena combat. Choose from a variety of characters and unique weapons to dominate your friends in local 4-player multiplayer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---rage-wars-europe-enfrit', 'N64', 'Turok - Rage Wars (Europe) (En,Fr,It)', '1999', 'Shooter', 'Acclaim Studios Austin', '4', 'Arena Shooter', 'Arena-based multiplayer FPS with multi-language support.', 'Win the Rage Wars tournament across diverse arenas.', 'The European multi-language release of the Turok brawler.', 'Turok - Rage Wars (Europe) (En,Fr,It) allows players to experience the intense arena action in multiple languages, featuring deep character customization and unique weapon skins.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---rage-wars-usa', 'N64', 'Turok - Rage Wars (USA)', '1999', 'Shooter', 'Acclaim Studios Austin', '4', 'Arena Shooter', 'Arena-based multiplayer first-person shooter with various modes.', 'Conquer the single-player trials and win the multiplayer cups.', 'The North American release of the Turok arena shooter.', 'Turok - Rage Wars (USA) is the ultimate party shooter for N64. With dozens of unlockable characters and a massive arsenal including the Cerebral Bore, it offers endless competitive fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok---rage-wars-usa-rev-a', 'N64', 'Turok - Rage Wars (USA) (Rev A)', '1999', 'Shooter', 'Acclaim Studios Austin', '4', 'Arena Shooter', 'Arena-based multiplayer FPS with crucial bug fixes.', 'Complete the "Trial" mode and unlock all secret characters.', 'An updated revision of Rage Wars that fixes game-breaking bugs.', 'Turok - Rage Wars (USA) (Rev A) is a rare and essential version that fixes the "Trial Mode" glitch, allowing players to finally 100% complete the game on original hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-2---seeds-of-evil-europe', 'N64', 'Turok 2 - Seeds of Evil (Europe)', '1998', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with massive levels and diverse enemies.', 'Destroy the five Energy Totems to keep the Primagen imprisoned.', 'The European release of the acclaimed Turok sequel.', 'Turok 2 - Seeds of Evil (Europe) is a technical masterpiece. Featuring the infamous Cerebral Bore and massive environments, it pushed the N64''s Expansion Pak to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-2---seeds-of-evil-europe-enfresit', 'N64', 'Turok 2 - Seeds of Evil (Europe) (En,Fr,Es,It)', '1998', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with multi-language support and deep lore.', 'Prevent the Primagen from escaping his ancient prison.', 'The European multi-language release of the Turok sequel.', 'Turok 2 - Seeds of Evil (Europe) (En,Fr,Es,It) offers the full, dark narrative of Joshua Fireseed in multiple languages, featuring intense combat and complex level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-2---seeds-of-evil-germany', 'N64', 'Turok 2 - Seeds of Evil (Germany)', '1998', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with localized German text and censored assets.', 'Neutralize the threats in the Port of Adia and beyond.', 'The German-localized version of Turok 2 with regional edits.', 'Turok 2 - Seeds of Evil (Germany) provides the epic scale of the sequel with specific modifications for the German market, including robot enemy swaps for humanoids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-2---seeds-of-evil-usa', 'N64', 'Turok 2 - Seeds of Evil (USA)', '1998', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with massive levels and diverse enemies.', 'Hunt down the Primagen''s forces across multiple worlds.', 'The North American release of the landmark Turok sequel.', 'Turok 2 - Seeds of Evil (USA) redefined what the N64 could do visually. With high-resolution graphics and a huge variety of weapons, it remains one of the most ambitious FPS games of its era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-2---seeds-of-evil-usa-rev-a', 'N64', 'Turok 2 - Seeds of Evil (USA) (Rev A)', '1998', 'Shooter', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with refined performance and bug fixes.', 'Save the lost souls and destroy the Energy Totems.', 'An updated revision of the North American Turok 2.', 'Turok 2 - Seeds of Evil (USA) (Rev A) offers a more stable experience with improved framerate in certain areas and minor logic fixes for the complex mission objectives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-3---shadow-of-oblivion-europe', 'N64', 'Turok 3 - Shadow of Oblivion (Europe)', '2000', 'Shooter', 'Acclaim Studios Austin', '1', 'First-Person Shooter', 'First-person shooter with a focus on cinematic storytelling.', 'Stop the Oblivion entity and save the Turok lineage.', 'The European release of the third entry in the series.', 'Turok 3 - Shadow of Oblivion (Europe) features two playable characters with unique paths. Experience a more linear, story-driven approach with improved character models and cinematic cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-3---shadow-of-oblivion-usa', 'N64', 'Turok 3 - Shadow of Oblivion (USA)', '2000', 'Shooter', 'Acclaim Studios Austin', '1', 'First-Person Shooter', 'First-person shooter with a focus on cinematic storytelling.', 'Choose between Danielle or Joseph to defeat the darkness.', 'The North American release of the cinematic Turok trilogy finale.', 'Turok 3 - Shadow of Oblivion (USA) concludes the N64 trilogy with style. Enjoy a more focused narrative and advanced lighting effects as you battle the cosmic threat of Oblivion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-adventures:-intense-challenge', 'N64', 'Twisted Adventures: Intense Challenge', '2022', 'Platformer', 'ROM Hack Community', '1', 'Challenge Platformer', 'High-difficulty 3D platforming with technical trials.', 'Complete a series of intense challenges to prove your skill.', 'A custom-built challenge mod for the Super Mario 64 engine.', 'Twisted Adventures: Intense Challenge is designed for expert players. Navigate through complex custom levels that require precise movement and timing to succeed on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-edge---extreme-snowboarding-europe', 'N64', 'Twisted Edge - Extreme Snowboarding (Europe)', '1999', 'Sports', 'Boss Game Studios', '2', 'Snowboarding', 'Snowboarding simulation with a focus on tricks and racing.', 'Win the world tour and master every mountain.', 'The European version of the extreme snowboarding title.', 'Twisted Edge - Extreme Snowboarding (Europe) offers fast-paced downhill action. Combine a deep trick system with competitive racing to earn your place at the top of the snowboarding world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-edge---extreme-snowboarding-usa', 'N64', 'Twisted Edge - Extreme Snowboarding (USA)', '1999', 'Sports', 'Boss Game Studios', '2', 'Snowboarding', 'Snowboarding simulation with a focus on tricks and racing.', 'Perform massive stunts and win the championship cup.', 'The North American release of the extreme snowboard racer.', 'Twisted Edge - Extreme Snowboarding (USA) features diverse riders and stylized environments. Master the "Twisted" physics and land huge combos to maximize your score on the slopes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('utchan-nanchan-no-hono-no-challenger---denryuu-ira-ira-bou-japan', 'N64', 'Utchan Nanchan no Hono no Challenger - Denryuu Ira Ira Bou (Japan)', '1997', 'Party', 'Taito', '2', 'Arcade Party Game', 'Skill-based action game based on a popular Japanese TV show.', 'Navigate a metal rod through a narrow electric maze without touching.', 'A Japan-exclusive game based on the "Electric Wand" challenge.', 'Utchan Nanchan no Hono no Challenger (Japan) is a high-tension skill game. Test your patience and steady hands across increasingly difficult mazes in this unique N64 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('v-rally-edition-99-europe-enfrde', 'N64', 'V-Rally Edition 99 (Europe) (En,Fr,De)', '1999', 'Racing', 'Eden Studios', '2', 'Rally Racing', 'Professional rally racing with licensed cars and tracks.', 'Win the world rally championship across diverse global stages.', 'The European version of the high-speed V-Rally sequel.', 'V-Rally Edition 99 (Europe) features realistic handling and diverse weather conditions. Drive iconic rally cars through mud, snow, and rain to prove your dominance on the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('v-rally-edition-99-japan', 'N64', 'V-Rally Edition 99 (Japan)', '1999', 'Racing', 'Eden Studios', '2', 'Rally Racing', 'Professional rally racing with licensed cars and tracks.', 'Master the Japanese rally circuits and unlock secret cars.', 'The Japanese localized version of the professional rally racer.', 'V-Rally Edition 99 (Japan) brings authentic rally action to Japanese N64 owners. Experience the thrill of point-to-point racing with refined physics and competitive AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('v-rally-edition-99-usa', 'N64', 'V-Rally Edition 99 (USA)', '1999', 'Racing', 'Eden Studios', '2', 'Rally Racing', 'Professional rally racing with licensed cars and tracks.', 'Climb the ranks to become the ultimate rally world champion.', 'The North American release of the acclaimed rally racing game.', 'V-Rally Edition 99 (USA) offers a deep career mode and split-screen multiplayer. Master the technical aspects of rally driving across 40 different tracks in this polished racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vampire-shadow-64', 'N64', 'Vampire Shadow 64', '2021', 'Horror', 'ROM Hack Community', '1', 'Horror Adventure', '3D action-platforming with gothic horror themes.', 'Navigate a dark, vampire-infested castle to find the hidden stars.', 'A dark and atmospheric horror-themed hack of Super Mario 64.', 'Vampire Shadow 64 transforms the Mushroom Kingdom into a gothic nightmare. Explore shadowy halls and battle supernatural forces in this unique and moody N64 fan adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8---2nd-offense-europe', 'N64', 'Vigilante 8 - 2nd Offense (Europe)', '2000', 'Action', 'Luxoflux', '2', 'Vehicle Combat', 'Vehicular combat with destructible environments and power-ups.', 'Eliminate all rival vehicles using an arsenal of heavy weapons.', 'The feature-rich sequel to the N64 vehicular combat hit.', 'Vigilante 8 - 2nd Offense (Europe) introduces more vehicles, transformable parts for different terrains, and a deep quest mode. Experience explosive 70s-style car combat across the PAL region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8---2nd-offense-usa', 'N64', 'Vigilante 8 - 2nd Offense (USA)', '2000', 'Action', 'Luxoflux', '2', 'Vehicle Combat', 'Vehicular combat with destructible environments and power-ups.', 'Master each character''s story and upgrade your vehicles.', 'The definitive North American release of the car-combat sequel.', 'Vigilante 8 - 2nd Offense (USA) features massive destructible arenas and a unique "salvage" system to improve your car. Battle through the alternate-history 1970s with high-octane weaponry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8-europe', 'N64', 'Vigilante 8 (Europe)', '1998', 'Action', 'Luxoflux', '2', 'Vehicle Combat', 'Vehicular combat with stylized 1970s cars and weaponry.', 'Outlast and outgun your opponents in open-arena battles.', 'The European release of the classic vehicular combat game.', 'Vigilante 8 (Europe) brings high-speed destruction to the N64. Choose your driver, collect specialized power-ups, and wreck the competition across iconic American landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8-france', 'N64', 'Vigilante 8 (France)', '1998', 'Action', 'Luxoflux', '2', 'Vehicle Combat', 'Vehicular combat with localized French text and menus.', 'Complete the missions to stop the international oil crisis.', 'The localized French version of the vehicular combat classic.', 'Vigilante 8 (France) offers the full, explosive experience of the first game for French fans. Master the special moves of each vehicle and dominate the arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8-germany', 'N64', 'Vigilante 8 (Germany)', '1998', 'Action', 'Luxoflux', '2', 'Vehicle Combat', 'Vehicular combat with localized German text and menus.', 'Neutralize the enemy threat in this 70s-inspired brawler.', 'The localized German version of the vehicular combat title.', 'Vigilante 8 (Germany) brings the funk and the firepower to German players. Experience intense car-to-car combat with smooth performance on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8-usa', 'N64', 'Vigilante 8 (USA)', '1998', 'Action', 'Luxoflux', '2', 'Vehicle Combat', 'Vehicular combat with stylized 1970s cars and weaponry.', 'Win the war on the highways and unlock hidden characters.', 'The original North American release of the car-combat giant.', 'Vigilante 8 (USA) is a cult classic known for its physics-based destruction and memorable characters. Use the environment to your advantage and unleash powerful special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('violence-killer---turok-new-generation-japan', 'N64', 'Violence Killer - Turok New Generation (Japan)', '1999', 'Shooter', 'Bits Studios', '1', 'First-Person Shooter', 'First-person shooter with a focus on cinematic storytelling.', 'Stop the Oblivion entity as either Danielle or Joseph.', 'The Japanese version of Turok 3: Shadow of Oblivion.', 'Violence Killer (Japan) features high-quality 3D models and intense shooter gameplay. Experience the final chapter of the Turok trilogy with Japanese localized text and cinematics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-chess-64-europe-enfrdeesitnl', 'N64', 'Virtual Chess 64 (Europe) (En,Fr,De,Es,It,Nl)', '1999', 'Board', 'Titus Software', '2', 'Chess Simulation', '3D chess simulation with multiple skill levels and tutorials.', 'Defeat the advanced AI or a friend in a game of strategy.', 'A comprehensive chess title with a built-in analytical engine.', 'Virtual Chess 64 (Europe) features a powerful AI that adjusts to your skill level. Learn the game with interactive tutorials or challenge the computer in a 3D-rendered environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-chess-64-usa-enfres', 'N64', 'Virtual Chess 64 (USA) (En,Fr,Es)', '1999', 'Board', 'Titus Software', '2', 'Chess Simulation', '3D chess simulation with multiple skill levels and tutorials.', 'Outmaster the grandmaster AI in a high-stakes match.', 'The North American release of the deep chess simulator.', 'Virtual Chess 64 (USA) is perfect for beginners and pros alike. With its intuitive interface and different 3D board styles, it''s the definitive chess experience on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-pool-64-europe', 'N64', 'Virtual Pool 64 (Europe)', '2000', 'Sports', 'Celeris', '4', 'Pool Simulation', 'Realistic pool and billiards simulation with physics.', 'Win tournaments and master the art of the trick shot.', 'The European release of the authentic 3D pool simulator.', 'Virtual Pool 64 (Europe) offers a 1:1 physics-based representation of pool. Move around the table in full 3D and calculate your angles to clear the table.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-pool-64-usa', 'N64', 'Virtual Pool 64 (USA)', '2000', 'Sports', 'Celeris', '4', 'Pool Simulation', 'Realistic pool and billiards simulation with physics.', 'Clear the table and become the world''s best pool shark.', 'The North American release of the acclaimed pool simulator.', 'Virtual Pool 64 (USA) is known for its incredible accuracy and perspective. Practice your shots or compete in a career mode that takes you from the bar to the pro circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-pro-wrestling-2---oudou-keishou-japan', 'N64', 'Virtual Pro Wrestling 2 - Oudou Keishou (Japan)', '2000', 'Wrestling', 'Aki Corporation', '4', 'Pro Wrestling', 'Professional wrestling simulation with a focus on realism.', 'Win the Triple Crown and master the king''s road of wrestling.', 'Widely considered the best wrestling game on the N64.', 'Virtual Pro Wrestling 2 (Japan) features the legendary AKI engine with deep grappling mechanics and a massive roster of Japanese wrestling icons in 3D.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-pro-wrestling-2-english-beta-3-by-sk-stylez', 'N64', 'Virtual Pro Wrestling 2 (English Beta 3 by S.K. Stylez)', '2001', 'Wrestling', 'ROM Hack Community', '4', 'Pro Wrestling', 'Professional wrestling simulation with English localization.', 'Experience the best of Japanese wrestling in English.', 'A community-translated beta of the legendary wrestling title.', 'Virtual Pro Wrestling 2 (English Beta 3) allows Western fans to navigate the menus and rosters of this Japanese masterpiece, featuring the refined "King''s Road" mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-pro-wrestling-64-japan', 'N64', 'Virtual Pro Wrestling 64 (Japan)', '1997', 'Wrestling', 'Aki Corporation', '4', 'Pro Wrestling', 'Professional wrestling simulation featuring mixed rosters.', 'Conquer the ring and win the various championship belts.', 'The first entry in the acclaimed VPW series on N64.', 'Virtual Pro Wrestling 64 (Japan) laid the groundwork for future hits like WCW/nWo Revenge. Experience the smooth grappling gameplay that made the AKI engine famous.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waialae-country-club---true-golf-classics-europe', 'N64', 'Waialae Country Club - True Golf Classics (Europe)', '1999', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Realistic golf simulation set on a world-famous course.', 'Finish under par at the legendary Hawaiian country club.', 'A professional golf title featuring the real Waialae course.', 'Waialae Country Club (Europe) brings authentic golf to the N64. Master the wind, club selection, and terrain in this detailed 3D sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waialae-country-club---true-golf-classics-europe-rev-a', 'N64', 'Waialae Country Club - True Golf Classics (Europe) (Rev A)', '1999', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Realistic golf simulation with minor bug fixes and polish.', 'Master the greens and win the professional tournament.', 'An updated revision of the European golf simulation.', 'Waialae Country Club (Europe) (Rev A) provides the most stable version of the game for PAL players, ensuring smooth performance during your 18-hole journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waialae-country-club---true-golf-classics-usa', 'N64', 'Waialae Country Club - True Golf Classics (USA)', '1999', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Realistic golf simulation set on a world-famous course.', 'Win the championship and master the challenging course.', 'The North American release of the True Golf Classics title.', 'Waialae Country Club (USA) features a 3D flyover of the course and intuitive swing mechanics. Experience a professional golf weekend from the comfort of your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waialae-country-club---true-golf-classics-usa-rev-a', 'N64', 'Waialae Country Club - True Golf Classics (USA) (Rev A)', '1999', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Realistic golf simulation with refined performance.', 'Achieve a hole-in-one and win the tournament cup.', 'An updated revision of the North American golf title.', 'Waialae Country Club (USA) (Rev A) offers technical improvements and minor logic fixes, making it the definitive way to play this golf classic on N64 hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waluigis-taco-stand', 'N64', 'Waluigi''s Taco Stand', '2022', 'Platformer', 'ROM Hack Community', '1', 'Meme Platformer', '3D comedy-platforming with a quirky narrative.', 'Pay off Waluigi''s debt by selling tacos and exploring the city.', 'A legendary and humorous ROM hack of Super Mario 64.', 'Waluigi''s Taco Stand is a masterpiece of internet humor. Explore a custom world, interact with funny NPCs, and fulfill taco orders in this surprisingly polished N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('war-gods-europe', 'N64', 'War Gods (Europe)', '1997', 'Fighting', 'Midway', '2', 'Arcade Fighting', '3D arena fighting game with mythological and sci-fi characters.', 'Defeat the ancient gods and claim the ultimate power.', 'A dark and gritty 3D brawler from the creators of Mortal Kombat.', 'War Gods (Europe) features unique characters with projectile and melee attacks. Master the "3D" movement and brutal finishers in this early N64 fighting experiment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('war-gods-usa', 'N64', 'War Gods (USA)', '1997', 'Fighting', 'Midway', '2', 'Arcade Fighting', '3D arena fighting game with mythological and sci-fi characters.', 'Prove your worth as a god and conquer the tournament.', 'The North American release of the aggressive 3D fighter.', 'War Gods (USA) is known for its high-poly models and intense action. Battle through a diverse roster of immortals to reach the final boss and claim divinity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-by-miigle', 'N64', 'WARIO by Miigle', '2021', 'Platformer', 'ROM Hack Community', '1', 'Character Mod', '3D platforming featuring a custom Wario character model.', 'Explore the world of Mario 64 with Wario''s unique charm.', 'A character-swap mod for Mario 64 featuring Wario.', 'WARIO by Miigle brings the greedy anti-hero to life with custom animations and textures. Experience the classic levels through Wario''s eyes in this fun fan modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warios-hint-art', 'N64', 'Wario''s Hint Art', '2021', 'Platformer', 'ROM Hack Community', '1', 'Experimental Platformer', '3D puzzle-exploration based on Wario Land hint art.', 'Find the hidden locations based on cryptic drawings.', 'A creative puzzle mod for the Super Mario 64 engine.', 'Wario''s Hint Art challenges your knowledge of the game world. Use Wario''s clues to find hidden stars and secrets in this clever and unique N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warios-karma-quest', 'N64', 'Wario''s Karma Quest', '2022', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D platforming with a focus on moral choices and karma.', 'Navigate levels and earn karma based on your actions.', 'A unique experimental mod for Super Mario 64.', 'Wario''s Karma Quest introduces a moral system to the platformer. Your decisions affect the game world and the ending in this innovative and thoughtful N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warped-worlds', 'N64', 'Warped Worlds', '2020', 'Platformer', 'ROM Hack Community', '1', 'Experimental Platformer', '3D platforming across shifting and distorted dimensions.', 'Collect stars while navigating through warped reality.', 'A high-concept ROM hack featuring reality-bending mechanics.', 'Warped Worlds offers a surreal experience where levels change as you play. Master the shifting physics and visuals to conquer this mind-bending N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warped-worlds-07-26-2020', 'N64', 'Warped Worlds 07-26-2020', '2020', 'Platformer', 'ROM Hack Community', '1', 'Experimental Platformer', '3D platforming with early-access warped mechanics.', 'Explore the first iteration of the warped world system.', 'An early build of the ambitious Warped Worlds project.', 'Warped Worlds 07-26-2020 provides a look at the development of this surreal mod. Experience early versions of the reality-shifting levels and technical experiments on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wave-race-64-europe-ende', 'N64', 'Wave Race 64 (Europe) (En,De)', '1996', 'Racing', 'Nintendo EAD', '2', 'Water Racing', 'Jet ski racing with realistic water physics and wave interaction.', 'Master the waves and finish first in the championship circuit.', 'The European version of the legendary N64 water racer.', 'Wave Race 64 (Europe) features incredible wave physics and tight controls. Navigate through buoy courses and master the dolphin jump in this atmospheric and high-speed jet ski classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wave-race-64-japan', 'N64', 'Wave Race 64 (Japan)', '1996', 'Racing', 'Nintendo EAD', '2', 'Water Racing', 'Jet ski racing with realistic water physics and wave interaction.', 'Win the cups across multiple difficulty levels in Japan.', 'The original Japanese release of the groundbreaking racer.', 'Wave Race 64 (Japan) set a new bar for sports games on the N64. Experience the soothing music and challenging ocean conditions as you race toward the professional championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wave-race-64-japan-rev-a', 'N64', 'Wave Race 64 (Japan) (Rev A)', '1996', 'Racing', 'Nintendo EAD', '2', 'Water Racing', 'Jet ski racing with refined performance and bug fixes.', 'Conquer the waves with improved game stability.', 'An updated Japanese revision of the jet ski classic.', 'Wave Race 64 (Japan) (Rev A) provides the same great racing with minor technical polish, ensuring smooth performance on the Nintendo 64 for Japanese players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wave-race-64-japan-rev-b-shindou-edition', 'N64', 'Wave Race 64 (Japan) (Rev B) (Shindou Edition)', '1997', 'Racing', 'Nintendo EAD', '2', 'Water Racing', 'Jet ski racing with Rumble Pak support and balance tweaks.', 'Experience the vibrations of the waves with the Shindou update.', 'The definitive Japanese update with Rumble Pak support.', 'Wave Race 64 (Japan) (Rev B) (Shindou Edition) is highly sought after by collectors. It adds Rumble Pak vibration and minor gameplay refinements to the original masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wave-race-64-usa', 'N64', 'Wave Race 64 (USA)', '1996', 'Racing', 'Nintendo EAD', '2', 'Water Racing', 'Jet ski racing with realistic water physics and wave interaction.', 'Become the world jet ski champion on your N64.', 'The North American release of the iconic water racer.', 'Wave Race 64 (USA) is a cornerstone of the system. With its unique "buoy" scoring system and varied weather effects, it remains one of the most satisfying racing experiences on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wave-race-64-usa-rev-a', 'N64', 'Wave Race 64 (USA) (Rev A)', '1996', 'Racing', 'Nintendo EAD', '2', 'Water Racing', 'Jet ski racing with refined performance and bug fixes.', 'Master the Drake Lake and Sunset Bay courses with polish.', 'An updated revision of the North American Wave Race 64.', 'Wave Race 64 (USA) (Rev A) offers the most stable experience for N64 players, featuring minor bug fixes and optimized code for the perfect high-speed ocean run.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-98-europe-enfrdees', 'N64', 'Wayne Gretzky''s 3D Hockey ''98 (Europe) (En,Fr,De,Es)', '1997', 'Sports', 'Midway', '4', 'Arcade Hockey', 'Fast-paced arcade ice hockey with a 3D engine.', 'Outscore your rivals in the ultimate 98-season tournament.', 'The European version of the Gretzky 98 update.', 'Wayne Gretzky''s 3D Hockey ''98 (Europe) offers improved graphics and AI over the original. Enjoy fast-hitting arcade action and licensed NHL teams across the PAL region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-98-usa', 'N64', 'Wayne Gretzky''s 3D Hockey ''98 (USA)', '1997', 'Sports', 'Midway', '4', 'Arcade Hockey', 'Fast-paced arcade ice hockey with a 3D engine.', 'Lead your team to the Stanley Cup in the 98 season.', 'The North American update for the Gretzky hockey series.', 'Wayne Gretzky''s 3D Hockey ''98 (USA) features realistic motion capture and iconic "on fire" goal moments. It’s the definitive way to play 3D arcade hockey on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-europe-enfrdees', 'N64', 'Wayne Gretzky''s 3D Hockey (Europe) (En,Fr,De,Es)', '1996', 'Sports', 'Midway', '4', 'Arcade Hockey', 'Fast-paced arcade ice hockey with high-impact gameplay.', 'Score goals and win the championship in the first 3D entry.', 'The European release of the original 3D hockey hit.', 'Wayne Gretzky''s 3D Hockey (Europe) brings the excitement of the rink to your TV. Featuring 3-on-3 and 5-on-5 modes, it’s a high-energy sports title with massive hits and fast goals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-japan', 'N64', 'Wayne Gretzky''s 3D Hockey (Japan)', '1996', 'Sports', 'Midway', '4', 'Arcade Hockey', 'Fast-paced arcade ice hockey with Japanese localization.', 'Conquer the rink as the Great One in this Japanese edition.', 'The Japanese localized version of the arcade hockey classic.', 'Wayne Gretzky''s 3D Hockey (Japan) provides the same intense action for the Japanese market. Master the slap shot and defensive checks in this polished N64 sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-usa', 'N64', 'Wayne Gretzky''s 3D Hockey (USA)', '1996', 'Sports', 'Midway', '4', 'Arcade Hockey', 'Fast-paced arcade ice hockey with high-impact gameplay.', 'Win the tournament and pull off legendary goals.', 'The North American release of the first 3D hockey game.', 'Wayne Gretzky''s 3D Hockey (USA) is an N64 launch-era favorite. Known for its "Fire" goals and arcade-style physics, it offers a fun and accessible take on professional hockey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-usa-rev-a', 'N64', 'Wayne Gretzky''s 3D Hockey (USA) (Rev A)', '1996', 'Sports', 'Midway', '4', 'Arcade Hockey', 'Fast-paced arcade ice hockey with bug fixes and polish.', 'Master the ice with the most stable version of the original.', 'An updated revision of the North American Gretzky hockey title.', 'Wayne Gretzky''s 3D Hockey (USA) (Rev A) ensures smooth performance and corrected team logic, making it the best version of the original 3D hockey experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-backstage-assault-usa', 'N64', 'WCW Backstage Assault (USA)', '2000', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Arena-based professional wrestling with a focus on weapons.', 'Defeat your rivals in a variety of non-ring locations.', 'A unique WCW title focused on backstage brawling.', 'WCW Backstage Assault (USA) skips the ring and goes straight to the parking lot and locker rooms. Use the environment as a weapon in this experimental N64 wrestling title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-mayhem-europe', 'N64', 'WCW Mayhem (Europe)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with a fast-paced arcade feel.', 'Win the WCW championship and master the special moves.', 'The European version of the first 3D WCW game from EA.', 'WCW Mayhem (Europe) features a huge roster and the ability to fight backstage. Experience the nitro-charged excitement of professional wrestling on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-mayhem-usa', 'N64', 'WCW Mayhem (USA)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with a fast-paced arcade feel.', 'Defeat the legends of the WCW in this 3D brawler.', 'The North American release of the high-energy WCW title.', 'WCW Mayhem (USA) includes full commentary and authentic entrance themes. Battle as your favorite wrestlers across multiple arenas in this action-packed sports game.');